from taf.hw.api.hbte import PA
from taf.hw.api.hbte.hbte import HbteException

from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.exceptions import AttenuationReadError, AttenuationSetError


class HBTE(Attenuator):
    MAX_SUPPORTED_ATTENUATION = 63
    MIN_SUPPORTED_ATTENUATION = 0

    def __init__(self, ip=None, port=5000, min_attenuation=None, max_attenuation=None):
        super(HBTE, self).__init__()
        self._ip = ip
        self._port = port
        self._pa = None
        self.min_attenuation = self._validate_min_attenuation(min_attenuation, self.MIN_SUPPORTED_ATTENUATION)
        self.max_attenuation = self._validate_max_attenuation(max_attenuation, self.MAX_SUPPORTED_ATTENUATION)

    def connect(self, **kwargs):
        self._pa = PA(self._ip, self._port)

    def disconnect(self, **kwargs):
        pass

    def _set_single_port_decibel_attenuation(self, rf_port_address, attenuation_value_db):
        try:
            self._pa.operateChannel(channelList=[rf_port_address], valueList=[attenuation_value_db])
        except HbteException as e:
            raise AttenuationSetError(str(e))

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        try:
            self._pa.operateChannel(channelList=rf_port_addresses, valueList=attenuation_values_db)
        except HbteException as e:
            raise AttenuationSetError(str(e))

    def read_port_attenuation(self, port):
        """
        Returns the attenuation value of attenuator.
        The result of queryChannel is a list with single value. e.g. [25.0]
        :return: attenuation value of attenuator
        :rtype: float
        """
        try:
            return self._pa.queryChannel(channelList=[port])[0]
        except HbteException as e:
            raise AttenuationReadError(str(e))

    def read_ports_attenuation(self, ports):
        """
        Returns the attenuation value of attenuator.
        The result of queryChannel is a list with multiple value. e.g. [15.0, 25.0]
        :return: attenuation value of attenuator
        :rtype: list[float]
        """
        try:
            return self._pa.queryChannel(channelList=ports)
        except HbteException as e:
            raise AttenuationReadError(str(e))
